from typing import TypedDict

from sqlty import SQL
from sqlty import NoParams

# --- Tuple types (generated by sqlty rewrite) ---

user_query = SQL[tuple[int, str], NoParams]("--sql\nSELECT id::INTEGER, name::TEXT FROM users")


# --- User-defined types (validated by sqlty check) ---


class User(TypedDict):
    id: int
    name: str
    email: str


user_detail = SQL[User, NoParams](
    "--sql\nSELECT id::INTEGER, name::TEXT, email::VARCHAR FROM users"
)
